// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
        // initialize via low-level call to avoid cross-file interface type friction:
        // initialize(_sGlp, _usdc, _rewardRouter, _glpManager, _dnGmxJuniorVault, _keeper)
        GlpManagerMock gm = new GlpManagerMock();
        bytes4 sel = bytes4(keccak256("initialize(address,address,address,address,address,address)"));
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(sel, address(1), address(2), address(3), address(gm), address(5), address(6))
        );
        require(ok, "init failed");
        // owner is now address(this)
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));
        if (caller == address(0)) caller = address(uint160(1));

        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: transferOwnership succeeds exactly when the caller is the
        // current owner, and in that case ownership is transferred to newOwner.
        assertTrue(ok == (caller == c.owner()) && (!ok || c.owner() == newOwner));
    }
}

contract GlpManagerMock {
    VaultMock public immutable vault;

    constructor() {
        vault = new VaultMock();
    }
}

contract VaultMock {
    function getMinPrice(address) external pure returns (uint256) {
        return 1e30;
    }
}
